using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Linq;
namespace FactoryArena.Editor {public static class ArtCatalog {
 public static void Capture(Camera c,string file,int w=1440,int h=1000){var rt=new RenderTexture(w,h,24);c.targetTexture=rt;c.Render();c.Render();RenderTexture.active=rt;var t=new Texture2D(w,h);t.ReadPixels(new Rect(0,0,w,h),0,0);t.Apply();File.WriteAllBytes(file,t.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;Object.DestroyImmediate(rt);Object.DestroyImmediate(t);}
 public static void Run(){var paths=AssetDatabase.FindAssets("t:Model",new[]{"Assets/FactoryArena/MODELS"}).Select(AssetDatabase.GUIDToAssetPath).OrderBy(x=>x).ToArray();var report=new System.Text.StringBuilder("path|bounds|materials\n");var c=new GameObject("Catalog Camera").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.12f,.18f,.24f);var root=new GameObject("Catalog inspection");root.transform.position=new Vector3(500,0,0);var light=new GameObject("Catalog light").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.2f;light.transform.rotation=Quaternion.Euler(40,-30,0);for(int batch=0;batch<paths.Length;batch+=20){for(int j=batch;j<Mathf.Min(batch+20,paths.Length);j++){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(paths[j]));g.transform.SetParent(root.transform,false);var rs=g.GetComponentsInChildren<Renderer>();Bounds b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);report.AppendLine(paths[j]+"|"+b.size+"|"+string.Join(",",rs.SelectMany(x=>x.sharedMaterials).Select(x=>x?x.name:"NULL").Distinct()));float s=2.8f/Mathf.Max(b.size.x,b.size.y,b.size.z);g.transform.localScale*=s;g.transform.localPosition=new Vector3((j-batch)%5*5,0,(j-batch)/5*5)-(b.center-root.transform.position)*s;foreach(var r in rs){var mats=r.sharedMaterials.Select(m=>{var n=new Material(Shader.Find("Universal Render Pipeline/Lit"));n.color=Color.white;n.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Path.GetDirectoryName(paths[j])+"/Textures/colormap.png");return n;}).ToArray();r.sharedMaterials=mats;}var label=new GameObject("Label").AddComponent<TextMesh>();label.transform.SetParent(root.transform,false);label.transform.localPosition=new Vector3((j-batch)%5*5,-.3f,(j-batch)/5*5-1.7f);label.transform.rotation=Quaternion.Euler(70,0,0);label.text=j+" "+Path.GetFileNameWithoutExtension(paths[j]);label.characterSize=.12f;label.fontSize=32;label.anchor=TextAnchor.MiddleCenter;}
 c.transform.position=root.transform.position+new Vector3(10,27,-8);c.transform.LookAt(root.transform.position+new Vector3(10,0,7));c.orthographic=true;c.orthographicSize=13;Capture(c,"Assets/FactoryArena/Generated/Redesign/Catalog_"+(batch/20)+".png");foreach(Transform t in root.transform.Cast<Transform>().ToArray())Object.DestroyImmediate(t.gameObject);}
 File.WriteAllText("Assets/FactoryArena/Generated/Redesign/ModelInventory.txt",report.ToString());Object.DestroyImmediate(root);Object.DestroyImmediate(c.gameObject);Object.DestroyImmediate(light.gameObject);}
}}

